export async function hedgedRead<T>(
  primaryCall: () => Promise<T>,
  backupCall: () => Promise<T>,
  p95ThresholdMs = 20
): Promise<T> {
  return new Promise((resolve, reject) => {
    let completed = false;
    const timer = setTimeout(() => {
      // Primary is taking too long; fire backup replica concurrently
      backupCall().then((res) => {
        if (!completed) { completed = true; resolve(res); }
      }).catch(() => {});
    }, p95ThresholdMs);

    primaryCall().then((res) => {
      clearTimeout(timer);
      if (!completed) { completed = true; resolve(res); }
    }).catch((err) => { if (!completed) reject(err); });
  });
}
